// CG-14b bounded typed int32 consumer oracle. Generated files are provided by
// tests/plugin.rs; frozen FDS/wire controls are not regenerated by this fixture.
pub mod default_checked {
    include!("default_checked.rs");
}
pub mod checked {
    include!("checked.rs");
}
pub mod original {
    include!("original.rs");
}

#[cfg(test)]
mod allocation_probe {
    use std::alloc::{GlobalAlloc, Layout, System};
    use std::cell::Cell;

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(false) };
        static ALLOCATIONS: Cell<usize> = const { Cell::new(0) };
    }
    struct CountedSystem;

    #[expect(
        unsafe_code,
        reason = "test-only allocator forwards unchanged layouts and pointers to System"
    )]
    unsafe impl GlobalAlloc for CountedSystem {
        unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
            if ENABLED.try_with(Cell::get).unwrap_or_default() {
                let _ = ALLOCATIONS.try_with(|count| count.set(count.get().saturating_add(1)));
            }
            unsafe { System.alloc(layout) }
        }

        unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
            unsafe {
                System.dealloc(pointer, layout);
            }
        }
    }

    #[global_allocator]
    static ALLOCATOR: CountedSystem = CountedSystem;

    struct EnabledScope;
    impl Drop for EnabledScope {
        fn drop(&mut self) {
            let _ = ENABLED.try_with(|enabled| enabled.set(false));
        }
    }

    pub fn during(operation: impl FnOnce()) -> usize {
        let before = ALLOCATIONS.with(Cell::get);
        ENABLED.with(|enabled| enabled.set(true));
        let scope = EnabledScope;
        operation();
        drop(scope);
        ALLOCATIONS.with(Cell::get) - before
    }
}

#[cfg(test)]
mod tests {
    use super::{checked, default_checked, original};
    use checked::extensions::{EXT_INT32, EXT_INT32_WITH_DEFAULT};
    use pbrs::{ClearAndParse, Parse, Serialize};

    #[test]
    fn defaults_presence_and_explicit_zero() {
        let mut value = checked::ExtendableMessage::new();
        assert_eq!(value.get_extension(&EXT_INT32), 0);
        assert_eq!(value.get_extension(&EXT_INT32_WITH_DEFAULT), 42);
        assert!(!value.has_extension(&EXT_INT32_WITH_DEFAULT));
        assert_eq!(value.serialize().unwrap(), [0_u8; 0]);
        value.set_extension(&EXT_INT32_WITH_DEFAULT, 42);
        assert!(value.has_extension(&EXT_INT32_WITH_DEFAULT));
        assert_eq!(value.serialize().unwrap(), [0xd0, 0x06, 42]);
        value.set_extension(&EXT_INT32_WITH_DEFAULT, 0);
        assert_eq!(value.serialize().unwrap(), [0xd0, 0x06, 0]);
        value.clear_extension(&EXT_INT32_WITH_DEFAULT);
        assert!(!value.has_extension(&EXT_INT32_WITH_DEFAULT));
        assert_eq!(value.get_extension(&EXT_INT32_WITH_DEFAULT), 42);
        assert_eq!(value.serialize().unwrap(), [0_u8; 0]);
    }

    #[test]
    fn duplicates_wrong_wire_and_unrelated_records() {
        // tag101=7, unknown tag200=9, tag101 fixed32=1, tag101=11,
        // unselected closed-enum tag105=99, unselected repeated tag103=3.
        let wire = [
            0xa8, 0x06, 7, 0xc0, 0x0c, 9, 0xad, 0x06, 1, 0, 0, 0, 0xa8, 0x06, 11, 0xc8, 0x06, 99,
            0xb8, 0x06, 3,
        ];
        let mut value = checked::ExtendableMessage::parse(&wire).unwrap();
        assert_eq!(value.get_extension(&EXT_INT32), 11);
        assert!(value.has_extension(&EXT_INT32));
        assert_eq!(value.serialize().unwrap(), wire);
        value.set_extension(&EXT_INT32, 4);
        assert_eq!(
            value.serialize().unwrap(),
            [
                0xc0, 0x0c, 9, 0xad, 0x06, 1, 0, 0, 0, 0xc8, 0x06, 99, 0xb8, 0x06, 3, 0xa8, 0x06, 4
            ]
        );
        value.clear_extension(&EXT_INT32);
        assert!(!value.has_extension(&EXT_INT32));
        assert_eq!(
            value.serialize().unwrap(),
            [
                0xc0, 0x0c, 9, 0xad, 0x06, 1, 0, 0, 0, 0xc8, 0x06, 99, 0xb8, 0x06, 3
            ]
        );
    }

    #[test]
    fn merge_negative_and_size_cache() {
        let mut value = checked::ExtendableMessage::parse(&[0xa8, 0x06, 7]).unwrap();
        assert_eq!(value.serialized_len(), 3);
        value.merge_from_bytes(&[0xa8, 0x06, 11]).unwrap();
        assert_eq!(value.get_extension(&EXT_INT32), 11);
        let source = checked::ExtendableMessage::parse(&[0xa8, 0x06, 12]).unwrap();
        pbrs::MergeFrom::merge_from(&mut value, &source);
        assert_eq!(value.get_extension(&EXT_INT32), 12);
        value.set_extension(&EXT_INT32, -1);
        let negative = [
            0xa8, 0x06, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 1,
        ];
        assert_eq!(value.serialize().unwrap(), negative);
        assert_eq!(value.serialized_len(), negative.len());
        assert_eq!(
            checked::ExtendableMessage::parse(&negative)
                .unwrap()
                .get_extension(&EXT_INT32),
            -1
        );
        value.clear_extension(&EXT_INT32);
        assert_eq!(value.serialized_len(), 0);
        assert_eq!(value.serialize().unwrap(), [0_u8; 0]);
    }

    #[test]
    fn same_layout_and_default_control() {
        assert_eq!(std::mem::size_of::<pbrs::UnknownFields>(), 8);
        assert_eq!(
            std::mem::size_of::<checked::ExtendableMessage>(),
            std::mem::size_of::<default_checked::ExtendableMessage>()
        );
        assert_eq!(
            std::mem::align_of::<checked::ExtendableMessage>(),
            std::mem::align_of::<default_checked::ExtendableMessage>()
        );
        let wire = include_bytes!("@ROOT@/tests/fixtures/edition2024/bin/extensions_populated.bin");
        let value = checked::ExtendableMessage::parse(wire).unwrap();
        let control = default_checked::ExtendableMessage::parse(wire).unwrap();
        assert_eq!(value.serialize().unwrap(), control.serialize().unwrap());
        assert_eq!(value.serialize().unwrap().as_slice(), wire);
        assert_eq!(value.get_extension(&EXT_INT32), 101);
        assert_eq!(value.get_extension(&EXT_INT32_WITH_DEFAULT), 99);
    }

    #[test]
    fn default_and_absent_access_allocate_nothing() {
        let allocations = super::allocation_probe::during(|| {
            let mut value = std::hint::black_box(checked::ExtendableMessage::new());
            assert_eq!(value.get_extension(&EXT_INT32_WITH_DEFAULT), 42);
            assert!(!value.has_extension(&EXT_INT32));
            value.clear_extension(&EXT_INT32);
            std::hint::black_box(value);
        });
        assert_eq!(allocations, 0);
        let mut value = checked::ExtendableMessage::new();
        value.set_extension(&EXT_INT32, 7);
        let allocations = super::allocation_probe::during(|| {
            value.set_extension(&EXT_INT32, 11);
            std::hint::black_box(value.get_extension(&EXT_INT32));
        });
        assert_eq!(allocations, 0);
    }

    #[test]
    fn nested_and_original_descriptors() {
        let mut checked = checked::ExtendableMessage::new();
        let nested = &checked::extensions::EXTENDABLE_MESSAGE_NESTED_SCOPED_EXTENSION;
        checked.set_extension(nested, 3);
        assert_eq!(checked.serialize().unwrap(), [0xb0, 0x09, 3]);
        let mut original = original::TestExtensions::new();
        assert_eq!(
            original.get_extension(&original::extensions::I32_EXTENSION_WITH_DEFAULT),
            100
        );
        original.set_extension(&original::extensions::I32_EXTENSION, 1);
        original.set_extension(&original::extensions::TEST_EXTENSIONS_NESTED_EXTENSION, 2);
        assert_eq!(original.serialize().unwrap(), [0x08, 1, 0xa0, 0x1f, 2]);
    }

    #[test]
    fn malformed_wire_still_fails_host_parser() {
        for wire in [&[0xa8, 0x06, 0x80][..], &[0xaa, 0x06, 3, 1][..], &[0][..]] {
            assert!(checked::ExtendableMessage::parse(wire).is_err());
        }
        // A valid length-delimited field at an int32 extension number is unknown.
        let wire = [0xaa, 0x06, 1, 9];
        let mut value = checked::ExtendableMessage::parse(&wire).unwrap();
        assert!(!value.has_extension(&EXT_INT32));
        value.clear_extension(&EXT_INT32);
        assert_eq!(value.serialize().unwrap(), wire);
        // Existing tag validation rejects overlong tags in both generated paths.
        let overlong_tag = [0xa8, 0x86, 0, 0x87, 0];
        assert!(checked::ExtendableMessage::parse(&overlong_tag).is_err());
        assert!(default_checked::ExtendableMessage::parse(&overlong_tag).is_err());
        // A canonical tag with an overlong value retains the typed value, while
        // serialization canonicalizes it exactly as the default generated path.
        let overlong_value = [0xa8, 0x06, 0x87, 0];
        let value = checked::ExtendableMessage::parse(&overlong_value).unwrap();
        let default_value = default_checked::ExtendableMessage::parse(&overlong_value).unwrap();
        assert_eq!(value.get_extension(&EXT_INT32), 7);
        assert_eq!(value.serialize().unwrap(), [0xa8, 0x06, 7]);
        assert_eq!(
            value.serialize().unwrap(),
            default_value.serialize().unwrap()
        );
    }
}
